// swift-tools-version:5.9
// Jiggicons for SwiftUI: the 80 free icons with their spring motion and
// spatial sound, and any icon from the full set added with the Jiggicons CLI. The icon data and sounds in Sources/Jiggicons/Resources are
// generated by tools/build-mobile.mjs in the Jiggicons repository.
import PackageDescription

let package = Package(
    name: "Jiggicons",
    platforms: [.iOS(.v15), .macOS(.v12), .tvOS(.v15), .visionOS(.v1)],
    products: [
        .library(name: "Jiggicons", targets: ["Jiggicons"]),
        .executable(name: "JiggiconsDemo", targets: ["JiggiconsDemo"]),
    ],
    targets: [
        .target(
            name: "Jiggicons",
            resources: [.copy("Resources/icons"), .copy("Resources/sounds")]
        ),
        // A macOS window with every free icon: `swift run JiggiconsDemo`.
        .executableTarget(name: "JiggiconsDemo", dependencies: ["Jiggicons"]),
        // Checks that run without Xcode: `swift run JiggiconsCheck`.
        .executableTarget(name: "JiggiconsCheck", dependencies: ["Jiggicons"]),
    ]
)
